protected void internalTransform(Body b, String phase, Map opts) {
  try {
    SootMethod thisMethod = b.getMethod();
    Chain units = b.getUnits();
    Iterator unitIt = units.iterator();
    Unit firstUnit = (Unit) units.getFirst();
    Unit lastUnit = (Unit) units.getLast();
    while (firstUnit instanceof IdentityStmt) {
      firstUnit = (Unit) units.getSuccOf(firstUnit);
    }
    if (lastUnit instanceof RetStmt || lastUnit instanceof ReturnStmt || lastUnit instanceof ReturnVoidStmt) {
      lastUnit = (Unit) units.getPredOf(lastUnit);
    }
    Local[] lockObj = new Local[maxLockObjs];
    boolean[] addedLocalLockObj = new boolean[maxLockObjs];
    SootField[] globalLockObj = new SootField[maxLockObjs];
    for (int i = 1; i < maxLockObjs; i++) {
      lockObj[i] = Jimple.v().newLocal("lockObj" + i, RefType.v("java.lang.Object"));
      addedLocalLockObj[i] = false;
      globalLockObj[i] = null;
    }
    if (!Scene.v().getMainClass().declaresMethod("void main(java.lang.String[])")) {
      throw new RuntimeException("couldn't find main() in mainClass");
    }
    for (int i = 1; i < maxLockObjs; i++) {
      if (useGlobalLock[i - 1]) {
        if (!addedGlobalLockObj[i]) {
          globalLockObj[i] = new SootField("globalLockObj" + i, RefType.v("java.lang.Object"), Modifier.STATIC | Modifier.PUBLIC);
          Scene.v().getMainClass().addField(globalLockObj[i]);
          addedGlobalLockObj[i] = true;
        } else {
          globalLockObj[i] = Scene.v().getMainClass().getFieldByName("globalLockObj" + i);
        }
      }
    }
    if (thisMethod.getSubSignature().equals("void main(java.lang.String[])")) {
      for (int i = 1; i < maxLockObjs; i++) {
        if (useGlobalLock[i - 1]) {
          addedLocalLockObj[i] = true;
          b.getLocals().add(lockObj[i]);
          units.insertBefore(Jimple.v().newAssignStmt(lockObj[i], Jimple.v().newNewExpr(RefType.v("java.lang.Object"))), (Stmt) firstUnit);
          SootClass objectClass = Scene.v().loadClassAndSupport("java.lang.Object");
          RefType type = RefType.v(objectClass);
          SootMethod initMethod = objectClass.getMethod("void <init>()");
          units.insertBefore(Jimple.v().newInvokeStmt(Jimple.v().newSpecialInvokeExpr(lockObj[i], initMethod.makeRef(), Collections.EMPTY_LIST)), (Stmt) firstUnit);
          units.insertBefore(Jimple.v().newAssignStmt(Jimple.v().newStaticFieldRef(globalLockObj[i].makeRef()), lockObj[i]), (Stmt) firstUnit);
        }
      }
    }
    int tempNum = 1;
    Iterator fsIt = fs.iterator();
    while (fsIt.hasNext()) {
      Transaction tn = ((TransactionFlowPair) fsIt.next()).tn;
      if (tn.setNumber == -1) {
        continue;
      }
      if (useGlobalLock[tn.setNumber - 1]) {
        if (!addedLocalLockObj[tn.setNumber]) {
          addedLocalLockObj[tn.setNumber] = true;
          b.getLocals().add(lockObj[tn.setNumber]);
          units.insertBefore(Jimple.v().newAssignStmt(lockObj[tn.setNumber], Jimple.v().newStaticFieldRef(globalLockObj[tn.setNumber].makeRef())), (Stmt) firstUnit);
        }
      } else {
        if (!addedLocalLockObj[tn.setNumber]) {
          b.getLocals().add(lockObj[tn.setNumber]);
          addedLocalLockObj[tn.setNumber] = true;
        }
        if (tn.lockObject instanceof Ref) {
          if (tn.lockObjectArrayIndex != null) {
            Local temp = Jimple.v().newLocal("lockObjTemp" + tempNum, ((Ref) tn.lockObject).getType());
            tempNum++;
            if (!b.getLocals().contains(temp)) {
              b.getLocals().add(temp);
            }
            units.insertBefore(Jimple.v().newAssignStmt(temp, tn.lockObject), (Stmt) tn.begin);
            units.insertBefore(Jimple.v().newAssignStmt(lockObj[tn.setNumber], Jimple.v().newArrayRef(temp, tn.lockObjectArrayIndex)), (Stmt) tn.begin);
          } else {
            units.insertBefore(Jimple.v().newAssignStmt(lockObj[tn.setNumber], tn.lockObject), (Stmt) tn.begin);
          }
        }
      }
      Value currentLockObject;
      if (useGlobalLock[tn.setNumber - 1] || tn.lockObject instanceof Ref) {
        currentLockObject = lockObj[tn.setNumber];
      } else {
        currentLockObject = tn.lockObject;
      }
      if (tn.wholeMethod) {
        thisMethod.setModifiers(thisMethod.getModifiers() & ~(Modifier.SYNCHRONIZED));
        synchronizeSingleEntrySingleExitBlock(b, (Stmt) firstUnit, (Stmt) lastUnit, (Local) currentLockObject);
      } else {
        if (tn.begin == null) {
          G.v().out.println("ERROR: Transaction has no beginning statement: " + tn.method.toString());
        }
        units.insertBefore(Jimple.v().newEnterMonitorStmt(currentLockObject), tn.begin);
        units.remove(tn.begin);
        Iterator endsIt = tn.ends.iterator();
        while (endsIt.hasNext()) {
          Stmt sEnd = (Stmt) endsIt.next();
          units.insertBefore(Jimple.v().newExitMonitorStmt(currentLockObject), sEnd);
          units.remove(sEnd);
        }
      }
      Iterator notifysIt = tn.notifys.iterator();
      while (notifysIt.hasNext()) {
        Stmt sNotify = (Stmt) notifysIt.next();
        units.insertBefore(Jimple.v().newInvokeStmt(Jimple.v().newVirtualInvokeExpr((Local) currentLockObject, sNotify.getInvokeExpr().getMethodRef().declaringClass().getMethod("void notifyAll()"), Collections.EMPTY_LIST)), sNotify);
        units.remove(sNotify);
      }
      Iterator waitsIt = tn.waits.iterator();
      while (waitsIt.hasNext()) {
        Stmt sWait = (Stmt) waitsIt.next();
        units.insertBefore(Jimple.v().newInvokeStmt(Jimple.v().newVirtualInvokeExpr((Local) currentLockObject, sWait.getInvokeExpr().getMethodRef().declaringClass().getMethod("void notifyAll()"), Collections.EMPTY_LIST)), sWait);
        units.remove(sWait);
      }
    }
  } catch (RuntimeException | NoSuchElementException e) {
    e.printStackTrace();
  }
}
